public class Main {
    public static void main(String[] args) {
        char letter = 'A';
        int code = letter;              // widening: a char fits in an int
        int next = code + 1;
        char nextLetter = (char) next;  // narrowing: needs a cast

        System.out.println(letter + " has code " + code);
        System.out.println("The next letter is " + nextLetter);
    }
}

